import noSampleSpecialCasing from './no-sample-special-casing.mjs';
import generatedGtMasks from './generated-gt-masks.mjs';
import optionalSkimageImport from './optional-skimage-import.mjs';

// gRatio's own pack: the measurement invariants and repo mechanics that are
// specific to this project and to no facet the canon homes. The project *class*
// (algorithm over similarly-formatted inputs, scored against annotated ground
// truth, improved in reviewable iterations) is the declared canon
// `research-project` pack — nothing here repeats it; what lives here is the
// g-ratio-specific residue: what may not be keyed on, what may not be imported,
// and which artifacts are generated rather than authored.
//
// Declared by hand as `local/gratio` in .claudinite-checks.json; never
// fingerprinted (detect/marker stay null) — a local pack is not seeded.
export default {
  id: 'gratio',
  detect: null,
  marker: null,
  prose: 'RULES.md',
  rules: [noSampleSpecialCasing, generatedGtMasks, optionalSkimageImport],
  skills: [],
  run_daily: [],
};
---RULES---
# gratio — the measurement invariants

This project's own pack: what is specific to measuring a myelin g-ratio from EM
cross-sections here, and to nothing the canon packs already home. The working
loop (show every step, ground truth annotated never invented, numbered
iterations, spikes vs. main path) is the declared `research-project` pack's — it
is not repeated here. Three rules of this pack are deterministic checks
(`README.md` lists them); what follows is the judgment that has no static
signature.

## Myelin rules stay scale-free and g-ratio-prior-free

`g = sqrt(A_axon / (A_axon + A_myelin))` is dimensionless, so nothing in the
measurement may depend on a magnification. Cap a myelin band by the axon's
**own measured ring thickness**, never by a pixel constant and never by a
fraction of the axon radius — a radius fraction bakes a g-ratio prior into a
g-ratio measurement, which is the one error the number cannot survive
(R20 in `docs/reference/user_masks.md`).

## Recall is the hard constraint, IoU is the objective

A missed axon does not merely lose one fibre: its myelin merges into a
neighbour's and corrupts *that* fibre's g. Tune for detection recall 1.0 with no
false positives first; only then maximise IoU. A change that trades a detection
for boundary accuracy is a regression however good the IoU delta looks.

## Two validation tiers — never merge them

The three `data/samples/` images have hand-drawn masks and score *segmentation*
(`evaluate_segmentation.py`, `report.py`). External sets such as
`data/external/macaque_cc/` have a **published g and no masks**, and score only
the *number* (`validate_external.py`). Never wire a mask-free set into the IoU
harness — the masks it would need do not exist, and inventing them turns the
baseline into an echo of the pipeline (`docs/reference/external_datasets.md`).

## Borders look hand-traced

Deliverable borders are smooth, roughly-closed shapes — not pixel staircases,
and not strict ovals fitted over a real, irregular boundary. A smoothing
tolerance that rounds off genuine shape (the elongated tadpole axons) is too
strong even when it scores well.

## Show `report.py`, and write the R-note

Present results with `python report.py` — the `[original | result | GT]` panels
plus per-neuron accuracy, recall, and predicted-vs-GT g — never the raw
`analyze.py` overlay. Every change that lands gets a numbered **R-note** in
`docs/reference/user_masks.md` recording what was wrong, what was tried, and
what was **rejected**; that rejection log is what stops the next session
re-walking a dead end. Cross-domain applicability goes to
`docs/reference/neurobiology_applications.md`, never into the algorithm body.
---TEST---
// Red-first fixtures for the gratio pack's checks: each rule must fire on a
// violating input and stay quiet on the repo as it actually stands.
// Run: node --test .claudinite/local/packs/gratio/
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import noSampleSpecialCasing from './no-sample-special-casing.mjs';
import generatedGtMasks from './generated-gt-masks.mjs';
import optionalSkimageImport from './optional-skimage-import.mjs';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');

// A world-scope context over literal file contents.
const ctxOf = (files) => ({
  files: Object.keys(files),
  read: (f) => (f in files ? files[f] : null),
  exists: (f) => f in files,
});

// The real repo as the clean fixture: every tracked file, read from disk.
const realCtx = () => {
  const tracked = execFileSync('git', ['-C', repoRoot, 'ls-files'], { encoding: 'utf8' })
    .split('\n').filter(Boolean);
  return {
    files: tracked,
    read: (f) => (existsSync(join(repoRoot, f)) ? readFileSync(join(repoRoot, f), 'utf8') : null),
    exists: (f) => existsSync(join(repoRoot, f)),
  };
};

test('no-sample-special-casing fires on code keyed to a stem', () => {
  const found = noSampleSpecialCasing.run(ctxOf({
    'gratio/pipeline.py': 'def segment(img, stem):\n    if stem == "sample_01":\n        thresh = 0.4\n',
  }));
  assert.equal(found.length, 1);
  assert.equal(found[0].line, 2);
});

test('no-sample-special-casing tolerates a sample cited in a comment or docstring', () => {
  assert.deepEqual(noSampleSpecialCasing.run(ctxOf({
    'gratio/pipeline.py': '"""Tuned against sample_02, the lone isolated fibre."""\n'
      + 'ring_tol = 1.4  # the elbow measured on sample_02\n',
  })), []);
});

test('no-sample-special-casing ignores the frozen research spikes', () => {
  assert.deepEqual(noSampleSpecialCasing.run(ctxOf({
    'gratio/phase2.py': 'g = cv2.imread(f"data/samples/sample_0{n}.png")\n',
  })), []);
});

test('optional-skimage-import fires on a module-level import', () => {
  const found = optionalSkimageImport.run(ctxOf({
    'gratio/lamella.py': 'import numpy as np\nfrom skimage.filters import sato\n',
  }));
  assert.equal(found.length, 1);
  assert.equal(found[0].line, 2);
});

test('optional-skimage-import tolerates the guarded function-local import', () => {
  assert.deepEqual(optionalSkimageImport.run(ctxOf({
    'gratio/lamella.py': 'def trace_lamellae(g):\n    try:\n'
      + '        from skimage.filters import sato\n    except Exception:\n        return None\n',
  })), []);
});

test('generated-gt-masks fires when a native mask changes alone', () => {
  const found = generatedGtMasks.run({
    changedFiles: ['data/samples/masks/native/sample_01_gt_axon.png'],
  });
  assert.equal(found.length, 1);
});

test('generated-gt-masks is quiet when the annotated crop changed too', () => {
  assert.deepEqual(generatedGtMasks.run({
    changedFiles: [
      'data/samples/masks/sample_01_masked.png',
      'data/samples/masks/native/sample_01_gt_axon.png',
    ],
  }), []);
});

test('the repo as it stands is clean under every rule', () => {
  const ctx = realCtx();
  assert.deepEqual(noSampleSpecialCasing.run(ctx), []);
  assert.deepEqual(optionalSkimageImport.run(ctx), []);
});

