// Local pack check — dependency-free by contract (it must load without the
// gitignored canon mount), so it returns plain finding objects rather than
// importing the engine's finding() helper.

// The main path is the `gratio` package minus the older research spikes:
// CLAUDE.md — "`gratio/phase1_*.py`, `phase2.py` | older research spikes, NOT
// the main path. 'The pipeline' = `gratio.segment`." The spikes legitimately
// hard-code `data/samples/sample_0{n}.png` as their driver (phase1_select.py:48,
// phase2.py:30) and are frozen; the CLI/report scripts at the repo root
// legitimately name the sample files as inputs. Only the library's decision
// logic is governed.
const SPIKE = /^gratio\/(phase1_.*|phase2)\.py$/;
const MAIN_PATH = (file) => file.startsWith('gratio/') && file.endsWith('.py') && !SPIKE.test(file);

const STEM = /sample_0\d/;

// Lines whose *code* (not comment, not docstring) names a sample stem. Comments
// citing a sample as the evidence for a tuned constant are the repo's normal
// practice and must not fire — gratio/pipeline.py's DEFAULTS block does it a
// dozen times ("1.4 is the elbow measured against the one isolated example
// (sample_02)"). Docstrings are skipped for the same reason
// (gratio/gt_register.py's module docstring names the sample rasters).
function codeLinesNamingAStem(text) {
  const hits = [];
  let fence = null; // the triple-quote currently open, if any
  text.split('\n').forEach((raw, i) => {
    let line = raw;
    if (fence) {
      const close = line.indexOf(fence);
      if (close === -1) return;
      line = line.slice(close + 3);
      fence = null;
    }
    // Consume complete same-line triple-quoted strings, then open a fence if one
    // is left dangling.
    for (;;) {
      const m = /"""|'''/.exec(line);
      if (!m) break;
      const rest = line.slice(m.index + 3);
      const close = rest.indexOf(m[0]);
      if (close === -1) { fence = m[0]; line = line.slice(0, m.index); break; }
      line = line.slice(0, m.index) + rest.slice(close + 3);
    }
    const code = line.split('#')[0];
    if (STEM.test(code)) hits.push({ line: i + 1, text: raw.trim() });
  });
  return hits;
}

const rule = {
  id: 'gratio-no-sample-special-casing',
  severity: 'blocking',
  description: 'Pipeline code must not branch on a sample stem (sample_01/02/03)',
  doc: '.claudinite/local/packs/gratio/RULES.md',
  why: 'a rule keyed on a stem scores well on the three-image set and generalises to nothing — the owner directive is "No single-sample special-casing" (CLAUDE.md; the R24 audit in docs/reference/user_masks.md)',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(MAIN_PATH)) {
      const text = ctx.read(file);
      if (text === null) continue;
      for (const hit of codeLinesNamingAStem(text)) {
        out.push({
          rule: rule.id, severity: rule.severity, file, line: hit.line,
          what: `executable code names a sample stem: ${hit.text.slice(0, 90)}`,
          why: rule.why,
          fix: 'express the rule in terms the image itself supplies (measured ring thickness, area fractions, neuron count) instead of the stem; if the sample is only the evidence for a constant, say so in a comment rather than in code',
          doc: rule.doc,
        });
      }
    }
    return out;
  },
};

export default rule;
export { codeLinesNamingAStem };
=== generated-gt-masks ===
// Local pack check — dependency-free by contract; returns plain finding objects.

// The generated ground truth. CLAUDE.md: "The masks under
// data/samples/masks/native/*_gt_*.png are generated, not hand-edited. Source of
// truth = the hand-annotated data/samples/masks/<stem>_masked.png crop. To fix
// GT, fix the crop (or the extraction) and regenerate — never edit the native
// PNGs (they get overwritten)."
const GENERATED = (f) => f.startsWith('data/samples/masks/native/') && f.endsWith('.png');

// Anything whose change legitimately explains a regenerated mask: the annotated
// crop, the extraction/registration code, or the builder that runs them.
const SOURCE = (f) =>
  /^data\/samples\/masks\/[^/]+_masked\.png$/.test(f) ||
  f === 'gratio/mask_extract.py' ||
  f === 'gratio/gt_register.py' ||
  f === 'build_ground_truth.py' ||
  f === 'extract_masks.py' ||
  f === 'data/samples/axon_seeds.json';

const rule = {
  id: 'gratio-generated-gt-masks',
  severity: 'blocking',
  description: 'Native GT masks change only alongside the annotation or the extraction that generates them',
  doc: '.claudinite/local/packs/gratio/RULES.md',
  scope: 'work',
  why: 'the native masks are regenerated output — a hand edit is silently overwritten by the next build_ground_truth.py run, and ground truth that was touched by hand is no longer annotated evidence',

  run(work) {
    const changed = work.changedFiles ?? [];
    const generated = changed.filter(GENERATED);
    if (!generated.length || changed.some(SOURCE)) return [];
    return [{
      rule: rule.id, severity: rule.severity,
      file: generated[0], line: null,
      what: `${generated.length} generated GT mask(s) changed with no change to the annotated crop or the extraction that produces them`,
      why: rule.why,
      fix: 'revert the native PNGs, fix data/samples/masks/<stem>_masked.png (or the extraction), then rerun `python extract_masks.py && python build_ground_truth.py` — see docs/reference/gt_from_masks.md',
      doc: rule.doc,
    }];
  },
};

export default rule;
=== optional-skimage ===
// Local pack check — dependency-free by contract; returns plain finding objects.

// scikit-image is a *dev* dependency here: requirements.txt pins only
// opencv-python-headless / numpy / scipy, while requirements-dev.txt adds
// scikit-image "for the opt-in outer-boundary refinements ... the pipeline
// no-ops without it". So the main path may use it, but only behind a guarded,
// function-local import — gratio/pipeline.py's membrane_outer_boundary and
// gratio/lamella.py's trace_lamellae both do `try: from skimage... except:
// return <unrefined>`. A module-level import would make `pip install -r
// requirements.txt` insufficient to run the pipeline at all.
const SPIKE = /^gratio\/(phase1_.*|phase2)\.py$/;
const MAIN_PATH = (file) => file.startsWith('gratio/') && file.endsWith('.py') && !SPIKE.test(file);

// Column 0 = module level. An indented import is inside a function or a
// try-block, which is the guarded shape this rule asks for.
const TOP_LEVEL_SKIMAGE = /^(?:import|from)\s+skimage\b/;

const rule = {
  id: 'gratio-optional-skimage-import',
  severity: 'blocking',
  description: 'scikit-image is imported lazily in the pipeline, never at module level',
  doc: '.claudinite/local/packs/gratio/RULES.md',
  why: 'scikit-image is in requirements-dev.txt only — a module-level import makes the whole pipeline unimportable for anyone who installed requirements.txt, instead of degrading to the unrefined result',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(MAIN_PATH)) {
      const text = ctx.read(file);
      if (text === null) continue;
      text.split('\n').forEach((line, i) => {
        if (!TOP_LEVEL_SKIMAGE.test(line)) return;
        out.push({
          rule: rule.id, severity: rule.severity, file, line: i + 1,
          what: `module-level scikit-image import: ${line.trim()}`,
          why: rule.why,
          fix: 'move the import inside the function that needs it, wrapped in try/except returning the unrefined result — the shape gratio/lamella.py trace_lamellae uses — or add scikit-image to requirements.txt if it has become mandatory',
          doc: rule.doc,
        });
      });
    }
    return out;
  },
};

export default rule;

# gratio pack (local)

gRatio's own pack: the g-ratio measurement invariants and repo mechanics that no
canon pack homes. The project *class* — algorithm over similarly-formatted
inputs, scored against annotated ground truth, improved in reviewable iterations
— is the declared canon `research-project` pack, and this pack deliberately
repeats none of it. Declared by hand as `local/gratio`.

## Checks (`rules`)

| Rule | Section (≤5 words) | How enforced |
|---|---|---|
| `gratio-no-sample-special-casing` | No single-sample special-casing | check — `gratio/*.py` (main path, spikes excluded) may not name a sample stem in code; comments and docstrings citing a sample as evidence are fine |
| `gratio-generated-gt-masks` | Native GT masks are generated | check (work scope) — `data/samples/masks/native/*.png` may not change without the annotated crop or the extraction that produces them |
| `gratio-optional-skimage-import` | scikit-image imported lazily | check — scikit-image is dev-only; the main path imports it inside a guarded function, so the pipeline degrades instead of failing to import |

## Prose (`RULES.md`) — by section

| Section (≤5 words) | How enforced |
|---|---|
| Myelin rules stay scale-free | prose |
| Recall is the hard constraint | prose |
| Two validation tiers, never merged | prose |
| Borders look hand-traced | prose |
| Show report.py, write R-note | prose |

